// 输出格式内容渲染（支持编号 + 子项层级）
function renderOutputBody(lines: string[]) {
  // 按编号分组
  const groups: { num: string; title: string; items: string[] }[] = [];
  let current: { num: string; title: string; items: string[] } | null = null;

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    // 顶层编号：1. xxx：
    const numMatch = trimmed.match(/^(\d+)\.\s+(.+?)[:：]\s*$/);
    if (numMatch) {
      if (current) groups.push(current);
      current = { num: numMatch[1], title: numMatch[2], items: [] };
      continue;
    }
    // 顶层编号但没有冒号结尾（如 "3. 视觉检索线索：" 后无子项但也算标题）
    const numMatch2 = trimmed.match(/^(\d+)\.\s+(.+)$/);
    const indent = (line.match(/^\s*/)?.[0].length ?? 0);
    if (numMatch2 && indent < 3) {
      if (current) groups.push(current);
      // 如果后面有子项就当分组，没有就当普通行
      current = { num: numMatch2[1], title: numMatch2[2].replace(/[:：]\s*$/, ''), items: [] };
      continue;
    }
    // 子项
    if (current) {
      current.items.push(line);
    }
  }
  if (current) groups.push(current);

  // 如果没有分组结构，直接渲染
  if (groups.length === 0 || groups.every((g) => g.items.length === 0 && !g.title)) {
    return renderContentLines(lines);
  }

  return (
    <div className="space-y-2.5">
      {groups.map((g, idx) => (
        <div key={idx}>
          <div className="flex items-center gap-2 mb-1.5">
            <span className="shrink-0 size-5 rounded-md bg-primary/15 text-primary text-[11px] font-bold flex items-center justify-center">
              {g.num}
            </span>
            <span className="text-sm font-medium text-foreground">{g.title}</span>
          </div>
          {g.items.length > 0 && (
            <div className="pl-7 space-y-1">
              {renderContentLines(g.items)}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

// 主提示词内容
