import { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { logger, copyToClipboard } from '@lark-apaas/client-toolkit-lite';
import api from '@/lib/api';
import { toast } from 'sonner';
import {
  searchInLocalLibrary,
  LIBRARY_TOTAL,
  LIBRARY_SHEETS,
  type IInfringementKeyword,
  SELLER_DEFENSE_BRANDS,
  searchBrandLibrary,
  type ISellerDefenseBrand,
} from '@/data/infringement-kwords';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Search,
  Loader2,
  AlertTriangle,
  AlertCircle,
  ShieldCheck,
  ExternalLink,
  FileWarning,
  HelpCircle,
  Info,
  Lightbulb,
  Gavel,
  Copy,
  Check,
  Building2,
  ShieldAlert,
  ChevronDown,
} from 'lucide-react';
import type { ThemeConfig } from '@/lib/theme';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';

interface PatentCheckLink {
  label: string;
  url: string;
}

interface PatentWarning {
  title: string;
  url: string;
}

interface PatentItem {
  patentNumber: string;
  title: string;
  assignee: string;
  date: string;
  url: string;
}

interface TroHit {
  caseNumber: string;
  brand: string;
  court: string;
  date: string;
  url: string;
}

interface TroResult {
  checked: boolean;
  /** 当前词条命中的 TRO 案件数 */
  total?: number;
  /** 123tro 全库案件总数 */
  totalAll?: number;
  hits?: TroHit[];
  updated?: string;
}

interface PatentCheckResult {
  risk: 'high' | 'medium' | 'low' | 'manual' | 'unknown' | 'error';
  riskReason?: string;
  /** 风险等级文字标签，后端返回时优先使用，覆盖默认 label */
  riskLabel?: string;
  /** 未命中时的建议/提示文案 */
  suggestion?: string;
  tro?: TroResult;
  searchLinks?: PatentCheckLink[];
  trademarkWarnings?: PatentWarning[];
  patents?: PatentItem[];
  disclaimer?: string;
  /** 本地词库命中的词条（前端填充） */
  localHits?: IInfringementKeyword[];
  /** 本地词库来源 sheet 统计 */
  libraryInfo?: {
    total: number;
    sheets: { name: string; count: number; description: string }[];
  };
  /** 数据源：local-词库 / api-后端联网 / mixed-两者合并 */
  dataSource?: 'local' | 'api' | 'mixed' | 'error';
}

interface PatentCheckCardProps {
  theme: ThemeConfig;
}

const RISK_CONFIG: Record<
  string,
  { label: string; icon: typeof AlertTriangle; color: string; bg: string; text: string }
> = {
  high: {
    label: '高风险',
    icon: AlertTriangle,
    color: 'text-destructive',
    bg: 'bg-destructive/10',
    text: 'text-destructive',
  },
  medium: {
    label: '中风险',
    icon: AlertCircle,
    color: 'text-amber-600',
    bg: 'bg-amber-500/10',
    text: 'text-amber-700',
  },
  low: {
    label: '低风险',
    icon: ShieldCheck,
    color: 'text-emerald-600',
    bg: 'bg-emerald-500/10',
    text: 'text-emerald-700',
  },
  manual: {
    label: '建议人工核实',
    icon: Lightbulb,
    color: 'text-yellow-600',
    bg: 'bg-yellow-500/10',
    text: 'text-yellow-700',
  },
  unknown: {
    label: '请填写关键词',
    icon: HelpCircle,
    color: 'text-muted-foreground',
    bg: 'bg-muted/50',
    text: 'text-muted-foreground',
  },
  error: {
    label: '服务异常',
    icon: FileWarning,
    color: 'text-destructive',
    bg: 'bg-destructive/10',
    text: 'text-destructive',
  },
};

export default function PatentCheckCard({ theme }: PatentCheckCardProps) {
  const [keywords, setKeywords] = useState('');
  const [isChecking, setIsChecking] = useState(false);
  const [result, setResult] = useState<PatentCheckResult | null>(null);
  // 品牌库 Tab
  const [brandTab, setBrandTab] = useState<'check' | 'brands'>('check');
  const [brandQuery, setBrandQuery] = useState('');
  const [copied, setCopied] = useState(false);
  const copyTimerRef = useRef<number | null>(null);

  // 清理复制状态定时器，避免卸载后 setState
  useEffect(() => {
    return () => {
      if (copyTimerRef.current) {
        clearTimeout(copyTimerRef.current);
        copyTimerRef.current = null;
      }
    };
  }, []);

  const brandResults = useMemo(() => searchBrandLibrary(brandQuery), [brandQuery]);

  // 一键复制排查结果
  const handleCopyResult = useCallback(async () => {
    if (!result) return;
    const lines: string[] = [];
    lines.push(`【侵权风险排查报告】`);
    lines.push(`关键词：${keywords}`);
    lines.push(`风险等级：${result.riskLabel || RISK_CONFIG[result.risk]?.label || result.risk}`);
    lines.push(`数据源：${result.dataSource === 'mixed' ? '本地词库+联网核查' : result.dataSource === 'api' ? '联网核查' : result.dataSource === 'local' ? '本地金山词库' : result.dataSource || '未知'}`);
    if (result.riskReason) {
      lines.push(`风险说明：${result.riskReason}`);
    }
    if (result.localHits && result.localHits.length > 0) {
      lines.push('');
      lines.push(`【本地词库命中 ${result.localHits.length} 条】`);
      result.localHits.slice(0, 20).forEach((h, i) => {
        const typeLabel = h.type === 'trademark' ? '商标' : h.type === 'copyright' ? '版权' : h.type === 'patent' ? '专利' : h.type === 'tro' ? 'TRO' : '图案';
        lines.push(`${i + 1}. [${typeLabel}/${h.risk === 'high' ? '高' : h.risk === 'medium' ? '中' : '低'}] ${h.keyword} - ${h.sheet}${h.brand ? ' · ' + h.brand : ''}${h.description ? ' - ' + h.description : ''}`);
      });
    }
    if (result.tro && result.tro.checked && result.tro.hits && result.tro.hits.length > 0) {
      lines.push('');
      lines.push(`【TRO 命中 ${result.tro.hits.length} 条 / 已核查 ${result.tro.totalAll || 6706} 条】`);
      result.tro.hits.forEach((t, i) => {
        lines.push(`${i + 1}. ${t.caseNumber} - ${t.brand} (${t.court}, ${t.date})`);
      });
    }
    if (result.patents && result.patents.length > 0) {
      lines.push('');
      lines.push(`【疑似相关专利 ${result.patents.length} 条】`);
      result.patents.forEach((p, i) => {
        lines.push(`${i + 1}. ${p.patentNumber} - ${p.title} (${p.assignee}, ${p.date})`);
      });
    }
    if (result.suggestion) {
      lines.push('');
      lines.push(`建议：${result.suggestion}`);
    }
    lines.push('');
    lines.push(`免责声明：结果仅供参考，不构成法律建议。`);
    try {
      await copyToClipboard(lines.join('\n'));
      setCopied(true);
      toast.success('排查报告已复制到剪贴板');
      if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
      copyTimerRef.current = window.setTimeout(() => setCopied(false), 2000);
    } catch (e) {
      logger.warn('[patent] 复制失败', String(e));
      toast.error('复制失败，请手动选择');
    }
  }, [result, keywords]);

  const handleCheck = useCallback(async () => {
    const trimmed = keywords.trim();
    if (!trimmed) {
      toast.info('请输入产品英文关键词');
      return;
    }

    // ========== 第 1 步：先查本地金山词库（1531 条，4 sheet） ==========
    // 立即展示本地匹配结果，用户不用等后端返回
    const localResult = searchInLocalLibrary(trimmed);
    let currentRisk: PatentCheckResult['risk'] = 'unknown';
    let currentReason = '';
    let currentLabel = '';
    let currentSuggestion = '';

    if (localResult && localResult.hits.length > 0) {
      currentRisk = localResult.highestRisk;
      currentLabel = localResult.riskLabel;
      currentReason = localResult.riskReason + '（本地词库已命中，正在联网深度核查...）';
      currentSuggestion = localResult.suggestion || '';
    } else if (localResult) {
      currentRisk = 'low';
      currentLabel = '词库未命中';
      currentReason = '本地 1531 条词库未直接命中，正在联网深度核查...';
      currentSuggestion = localResult.suggestion || '';
    }

    // 先把本地结果渲染出来
    setResult({
      risk: currentRisk,
      riskReason: currentReason,
      riskLabel: currentLabel,
      suggestion: currentSuggestion,
      localHits: localResult?.hits || [],
      libraryInfo: {
        total: LIBRARY_TOTAL,
        sheets: LIBRARY_SHEETS,
      },
      dataSource: 'local',
      searchLinks: [],
      trademarkWarnings: [],
      patents: [],
    });
    setIsChecking(true);

    try {
      // 纯关键词走 GET，30 秒超时
      const response = await api.get('/patent-check', {
        params: { keywords: trimmed },
        timeout: 30000,
      });
      const data = (response.data?.data ?? response.data) as PatentCheckResult;

      // ========== 第 2 步：合并后端结果与本地词库 ==========
      // 风险等级取两者最高（更保守）
      const riskRank: Record<string, number> = { high: 3, medium: 2, low: 1, unknown: 0, error: -1, manual: 2 };
      const localRank = currentRisk ? (riskRank[currentRisk] ?? 0) : 0;
      const apiRank = data?.risk ? (riskRank[data.risk] ?? 0) : 0;
      const finalRisk = apiRank >= localRank ? (data?.risk || 'unknown') : currentRisk;
      const hasBoth = localResult && localResult.hits.length > 0 && data;

      const mergedReason = hasBoth
        ? `${data.riskReason || '联网核查完成'} 本地词库命中 ${localResult!.hits.length} 条（${LIBRARY_SHEETS.map(s => s.name).join(' / ')}）`
        : (data.riskReason || currentReason);

      setResult({
        risk: finalRisk,
        riskReason: mergedReason,
        riskLabel: data.riskLabel || currentLabel,
        suggestion: data.suggestion || currentSuggestion,
        tro: data.tro,
        searchLinks: data.searchLinks || [],
        trademarkWarnings: data.trademarkWarnings || [],
        patents: data.patents || [],
        disclaimer: data.disclaimer,
        localHits: localResult?.hits || [],
        libraryInfo: {
          total: LIBRARY_TOTAL,
          sheets: LIBRARY_SHEETS,
        },
        dataSource: hasBoth ? 'mixed' : 'api',
      });
    } catch (err: any) {
      const msg = err?.response?.data?.error || err?.message || '联网核查请求失败';
      logger.warn('侵权排查联网接口失败:', String(err));

      // 后端失败不影响本地词库结果展示 —— 降级到纯本地模式
      if (localResult && localResult.hits.length > 0) {
        setResult(prev => ({
          ...prev,
          risk: localResult.highestRisk,
          riskLabel: localResult.riskLabel,
          riskReason: localResult.riskReason + '（联网深度核查暂不可用，当前结果基于本地 1531 条金山词库）',
          suggestion: localResult.suggestion,
          dataSource: 'local',
        }));
        toast.info('联网核查暂时不可用，已展示本地词库匹配结果');
      } else {
        setResult({
          risk: 'error',
          riskReason: '本地词库未命中，且联网核查服务暂时不可用（' + msg + '）',
          riskLabel: '服务异常',
          suggestion: '请稍后重试，或手动用下方搜索引擎链接核查。',
          localHits: [],
          libraryInfo: {
            total: LIBRARY_TOTAL,
            sheets: LIBRARY_SHEETS,
          },
          dataSource: 'error',
          searchLinks: [],
          trademarkWarnings: [],
          patents: [],
        });
        toast.info('联网核查暂时不可用，本地词库未命中');
      }
    } finally {
      setIsChecking(false);
    }
  }, [keywords]);

  const riskCfg = RISK_CONFIG[result?.risk || 'unknown'] || RISK_CONFIG.unknown;
  const RiskIcon = riskCfg.icon;
  const hasTroHits = result?.tro?.checked && (result.tro.hits?.length ?? 0) > 0;
  const showTroWarning = result?.risk === 'high' && hasTroHits;
  const hasSearchLinks = !!result?.searchLinks && result.searchLinks.length > 0;
  const riskDisplayLabel = showTroWarning
    ? '⚠️ TRO 起诉风险'
    : result?.riskLabel || riskCfg.label;

  return (
    <Card className="border-0 shadow-sm">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <Search className="size-4" style={{ color: theme.primary }} />
            侵权风险排查
          </CardTitle>
          <Badge
            variant="outline"
            className="text-[10px] font-normal h-5 border-0"
            style={{
              backgroundColor: theme.primaryLight ? theme.primaryLight + '40' : 'hsl(226 100% 96% / 0.5)',
              color: theme.primary,
            }}
          >
            联网排查 · 结果仅供参考
          </Badge>
        </div>
        <CardDescription className="text-xs">
          输入产品英文关键词，快速排查商标/专利/TRO 侵权风险
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Tab 切换 */}
        <div className="flex items-center gap-1 border-b border-border/60 pb-1">
          <button
            onClick={() => setBrandTab('check')}
            className={`px-3 py-1.5 text-xs font-medium rounded-t-md transition-colors ${
              brandTab === 'check'
                ? 'text-foreground bg-muted/40 border-b-2 -mb-px'
                : 'text-muted-foreground hover:text-foreground'
            }`}
            style={brandTab === 'check' ? { borderColor: theme.primary } : undefined}
          >
            <Search className="size-3.5 inline mr-1.5" />
            关键词排查
          </button>
          <button
            onClick={() => setBrandTab('brands')}
            className={`px-3 py-1.5 text-xs font-medium rounded-t-md transition-colors ${
              brandTab === 'brands'
                ? 'text-foreground bg-muted/40 border-b-2 -mb-px'
                : 'text-muted-foreground hover:text-foreground'
            }`}
            style={brandTab === 'brands' ? { borderColor: theme.primary } : undefined}
          >
            <Building2 className="size-3.5 inline mr-1.5" />
            SellerDefense 品牌库
          </button>
        </div>

        {/* ====== Tab 1：关键词排查 ====== */}
        {brandTab === 'check' && (
          <>
            {/* 输入区 */}
        <div className="space-y-3">
          <div className="relative">
            <Search className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
            <input
              type="text"
              value={keywords}
              onChange={(e) => setKeywords(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleCheck();
              }}
              placeholder="water bottle, cap，逗号分隔 1~3 个"
              className="w-full h-9 pl-9 pr-3 rounded-md border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring focus:border-ring"
            />
          </div>

          <div className="flex justify-end">
            <Button
              size="sm"
              onClick={handleCheck}
              disabled={isChecking}
              className="h-9"
              style={
                isChecking
                  ? undefined
                  : { backgroundColor: theme.primary, borderColor: theme.primary }
              }
            >
              {isChecking ? (
                <>
                  <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                  排查中
                </>
              ) : (
                <>
                  <Search className="size-3.5 mr-1.5" />
                  开始排查
                </>
              )}
            </Button>
          </div>
        </div>

        {/* 结果区 */}
        {result && !isChecking && (
          <div className="space-y-3 pt-1">
            {/* 风险徽章 */}
            <div
              className="flex items-center gap-2 px-3 py-2 rounded-lg"
              style={{
                backgroundColor: showTroWarning
                  ? 'rgba(220, 38, 38, 0.12)'
                  : result.risk === 'low'
                    ? 'rgba(16, 185, 129, 0.08)'
                    : result.risk === 'medium'
                      ? 'rgba(245, 158, 11, 0.08)'
                      : result.risk === 'high'
                        ? 'rgba(239, 68, 68, 0.08)'
                        : result.risk === 'manual'
                          ? 'rgba(234, 179, 8, 0.08)'
                          : 'rgba(148, 163, 184, 0.08)',
              }}
            >
              <AlertTriangle
                className="size-4 shrink-0"
                style={{
                  color: showTroWarning
                    ? '#dc2626'
                    : result.risk === 'low'
                      ? '#10b981'
                      : result.risk === 'medium'
                        ? '#f59e0b'
                        : result.risk === 'high'
                          ? '#ef4444'
                          : result.risk === 'manual'
                            ? '#eab308'
                            : '#94a3b8',
                }}
              />
              <span
                className="text-sm font-semibold"
                style={{
                  color: showTroWarning
                    ? '#b91c1c'
                    : result.risk === 'low'
                      ? '#059669'
                      : result.risk === 'medium'
                        ? '#d97706'
                        : result.risk === 'high'
                          ? '#dc2626'
                          : result.risk === 'manual'
                            ? '#ca8a04'
                            : '#64748b',
                }}
              >
                {riskDisplayLabel}
              </span>
            </div>

            {/* 风险说明 */}
            {result.riskReason && (
              <p className="text-sm text-foreground/80 leading-relaxed">
                {result.riskReason}
              </p>
            )}

            {/* 本地金山词库命中详情 */}
            {result.localHits && result.localHits.length > 0 && (
              <div className="border border-border/60 rounded-lg p-3 bg-muted/20 space-y-2">
                <div className="text-xs font-medium text-foreground flex items-center justify-between">
                  <span className="flex items-center gap-1.5">
                    <FileWarning className="size-3.5" style={{ color: theme.primary }} />
                    本地词库命中 {result.localHits.length} 条
                    {result.libraryInfo && (
                      <span className="text-muted-foreground font-normal">（金山文档 · {result.libraryInfo.total} 条 · 4 sheet）</span>
                    )}
                  </span>
                </div>
                <div className="space-y-1.5 max-h-48 overflow-y-auto">
                  {result.localHits.slice(0, 15).map((hit, i) => (
                    <div key={i} className="flex items-start gap-2 px-2 py-1.5 rounded-md bg-background/70 border border-border/40">
                      <Badge
                        variant={hit.risk === 'high' ? 'destructive' : hit.risk === 'medium' ? 'secondary' : 'outline'}
                        className="shrink-0 mt-0.5 text-[10px] px-1.5 py-0 h-auto"
                      >
                        {hit.risk === 'high' ? '高' : hit.risk === 'medium' ? '中' : '低'}
                      </Badge>
                      <div className="flex-1 min-w-0">
                        <div className="text-xs font-medium text-foreground flex items-center gap-1.5">
                          {hit.keyword}
                          <span className="text-[10px] text-muted-foreground font-normal">
                            {hit.type === 'trademark' ? '商标' : hit.type === 'copyright' ? '版权' : hit.type === 'patent' ? '专利' : hit.type === 'tro' ? 'TRO' : '图案'}
                            {' · '}{hit.sheet}
                          </span>
                        </div>
                        {hit.description && (
                          <p className="text-[11px] text-muted-foreground leading-relaxed mt-0.5 line-clamp-2">
                            {hit.brand && <span className="font-medium text-foreground/80">{hit.brand}：</span>}
                            {hit.description}
                          </p>
                        )}
                      </div>
                    </div>
                  ))}
                  {result.localHits.length > 15 && (
                    <p className="text-[11px] text-muted-foreground text-center pt-1">
                      还有 {result.localHits.length - 15} 条命中，建议精简关键词精确排查
                    </p>
                  )}
                </div>
                {result.libraryInfo && (
                  <div className="flex flex-wrap gap-x-3 gap-y-1 pt-1 border-t border-border/40">
                    {result.libraryInfo.sheets.map((s, i) => (
                      <span key={i} className="text-[10px] text-muted-foreground">
                        {s.name} · {s.count}条
                      </span>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* 词库来源说明（未命中时显示） */}
            {result.libraryInfo && (!result.localHits || result.localHits.length === 0) && result.risk !== 'error' && (
              <div className="text-[11px] text-muted-foreground flex items-center gap-1.5">
                <Info className="size-3.5 shrink-0" />
                <span>
                  已扫描本地金山词库 {result.libraryInfo.total} 条（{result.libraryInfo.sheets.map(s => s.name).join(' / ')}），未直接命中
                </span>
              </div>
            )}

            {/* 未命中/人工核实提示文案 */}
            {result.suggestion && result.risk !== 'high' && (
              <div className="text-xs text-muted-foreground leading-relaxed flex gap-2">
                <Lightbulb className="size-3.5 shrink-0 mt-0.5" style={{ color: '#ca8a04' }} />
                <span>{result.suggestion}</span>
              </div>
            )}

            {/* ⚖️ 最新美国 TRO 案件 */}
            {result.tro && (
              <div>
                {result.tro.checked ? (
                  <>
                    <div className="text-[11px] text-muted-foreground mb-2 flex items-center gap-1.5">
                      <Gavel className="size-3.5" style={{ color: theme.primary }} />
                        <span>
                          ⚖️ 已核查 123tro TRO 案件 {result.tro.totalAll ?? 6706} 条（全库）
                          {result.tro.updated ? `· 更新至 ${result.tro.updated}` : ''}
                        </span>
                    </div>
                    {hasTroHits ? (
                      <div className="border border-destructive/30 rounded-lg p-2.5 space-y-2 bg-destructive/5">
                        <div className="text-xs font-semibold text-destructive flex items-center gap-1.5">
                          <AlertTriangle className="size-3.5" />
                          命中 {result.tro.hits!.length} 条相关 TRO 起诉
                        </div>
                        <div className="space-y-1.5">
                          {result.tro.hits!.map((hit, i) => (
                            <UniversalLink
                              key={i}
                              to={hit.url}
                              target="_blank"
                              rel="noreferrer"
                              className="block px-2.5 py-2 rounded-md bg-background/70 hover:bg-background transition-colors border border-destructive/20"
                            >
                              <div className="flex items-start justify-between gap-2 mb-0.5">
                                <span className="text-[11px] font-mono font-medium text-destructive">
                                  {hit.caseNumber}
                                </span>
                                <span className="text-[11px] text-muted-foreground shrink-0">
                                  {hit.date}
                                </span>
                              </div>
                              <div className="text-sm font-medium text-foreground line-clamp-1 mb-0.5">
                                🏛️ {hit.brand}
                              </div>
                              <div className="text-[11px] text-muted-foreground line-clamp-1">
                                法院：{hit.court}
                              </div>
                            </UniversalLink>
                          ))}
                        </div>
                      </div>
                    ) : (
                      <div className="border border-emerald-500/30 rounded-lg p-3 bg-emerald-500/5">
                        <div className="flex items-start gap-2">
                          <ShieldCheck className="size-4 shrink-0 text-emerald-600 mt-0.5" />
                          <div className="text-xs text-emerald-700 leading-relaxed">
                            未命中您的关键词，近期无相关 TRO 起诉，仍建议按下方链接人工核实专利/商标。
                          </div>
                        </div>
                      </div>
                    )}
                  </>
                ) : (
                  <div className="border border-border/50 rounded-lg p-3 bg-muted/30">
                    <div className="flex items-start gap-2">
                      <HelpCircle className="size-4 shrink-0 text-muted-foreground mt-0.5" />
                      <div className="text-xs text-muted-foreground leading-relaxed">
                        TRO 案件源暂不可用，已尽力核查。
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* 一键检索核实链接 */}
            {hasSearchLinks && (
              <div>
                <div className="text-xs font-medium text-foreground mb-2 flex items-center gap-1.5">
                  <ExternalLink className="size-3.5" style={{ color: theme.primary }} />
                  一键检索核实
                </div>
                <div className="space-y-1.5">
                  {result.searchLinks.map((link, i) => (
                    <UniversalLink
                      key={i}
                      to={link.url}
                      target="_blank"
                      rel="noreferrer"
                      className="flex items-center justify-between px-3 py-2 rounded-md text-sm hover:bg-muted/50 transition-colors group"
                    >
                      <span className="truncate text-foreground/85 group-hover:text-foreground">
                        🔗 {link.label}
                      </span>
                      <ExternalLink className="size-3 shrink-0 text-muted-foreground group-hover:text-foreground" />
                    </UniversalLink>
                  ))}
                </div>
              </div>
            )}

            {/* 侵权/TRO 资讯 */}
            {result.trademarkWarnings && result.trademarkWarnings.length > 0 && (
              <div>
                <div className="text-xs font-medium text-foreground mb-2 flex items-center gap-1.5">
                  <FileWarning className="size-3.5" style={{ color: theme.primary }} />
                  侵权 / TRO 资讯
                </div>
                <div className="space-y-1.5">
                  {result.trademarkWarnings.map((w, i) => (
                    <UniversalLink
                      key={i}
                      to={w.url}
                      target="_blank"
                      rel="noreferrer"
                      className="flex items-center justify-between px-3 py-2 rounded-md text-sm hover:bg-muted/50 transition-colors group"
                    >
                      <span className="truncate text-foreground/85 group-hover:text-foreground">
                        📰 {w.title}
                      </span>
                      <ExternalLink className="size-3 shrink-0 text-muted-foreground group-hover:text-foreground" />
                    </UniversalLink>
                  ))}
                </div>
              </div>
            )}

            {/* 疑似相关专利 */}
            {result.patents && result.patents.length > 0 && (
              <div>
                <div className="text-xs font-medium text-foreground mb-2 flex items-center gap-1.5">
                  <Info className="size-3.5" style={{ color: theme.primary }} />
                  疑似相关专利（{result.patents.length} 条）
                </div>
                <div className="space-y-2">
                  {result.patents.map((p, i) => (
                    <UniversalLink
                      key={i}
                      to={p.url}
                      target="_blank"
                      rel="noreferrer"
                      className="block p-3 rounded-lg border border-border/50 hover:border-border hover:bg-muted/30 transition-all"
                    >
                      <div className="flex items-start justify-between gap-2 mb-1">
                        <span
                          className="text-xs font-mono font-medium"
                          style={{ color: theme.primary }}
                        >
                          {p.patentNumber}
                        </span>
                        <span className="text-[11px] text-muted-foreground shrink-0">
                          {p.date}
                        </span>
                      </div>
                      <div className="text-sm font-medium text-foreground line-clamp-1 mb-0.5">
                        {p.title}
                      </div>
                      <div className="text-xs text-muted-foreground line-clamp-1">
                        权利人：{p.assignee}
                      </div>
                    </UniversalLink>
                  ))}
                </div>
              </div>
            )}

            {/* 免责声明 */}
            {result.disclaimer && (
              <p className="text-[11px] text-muted-foreground leading-relaxed pt-1 border-t border-border/40">
                ⚠️ {result.disclaimer}
              </p>
            )}
          </div>
        )}

        {/* 空态提示（未排查过） */}
        {!result && !isChecking && (
          <div className="flex flex-col items-center justify-center py-6 text-center">
            <div
              className="size-12 rounded-full flex items-center justify-center mb-3"
              style={{ backgroundColor: theme.primaryLight ? theme.primaryLight + '40' : 'hsl(226 100% 96% / 0.5)' }}
            >
              <ShieldCheck className="size-6" style={{ color: theme.primary }} />
            </div>
            <p className="text-sm text-foreground/70 mb-1">
              输入产品英文关键词，一键排查侵权风险
            </p>
            <p className="text-xs text-muted-foreground">
              覆盖商标、专利、TRO 预警等多维度
            </p>
          </div>
        )}

        {/* 一键复制结果（有结果时显示） */}
        {result && !isChecking && (
          <div className="flex justify-end pt-2 border-t border-border/50">
            <Button
              size="sm"
              variant="outline"
              onClick={handleCopyResult}
              className="h-8 text-xs"
            >
              {copied ? (
                <>
                  <Check className="size-3.5 mr-1.5 text-emerald-600" />
                  已复制
                </>
              ) : (
                <>
                  <Copy className="size-3.5 mr-1.5" />
                  复制排查报告
                </>
              )}
            </Button>
          </div>
        )}
          </>
        )}

        {/* ====== Tab 2：SellerDefense 品牌库 ====== */}
        {brandTab === 'brands' && (
          <div className="space-y-3">
            {/* 搜索框 */}
            <div className="relative">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
              <input
                type="text"
                value={brandQuery}
                onChange={(e) => setBrandQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    // 输入即过滤，回车仅触发 focus 变化的视觉反馈
                    (e.target as HTMLInputElement).blur();
                    setTimeout(() => (e.target as HTMLInputElement).focus(), 0);
                  }
                }}
                placeholder="输入品牌名/类目/律所开始排查，如 Dior、Barbie、(G)I-DLE、鞋类、GBC"
                className="w-full h-9 pl-9 pr-3 rounded-md border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring focus:border-ring"
              />
            </div>

            {/* 未输入：引导提示 */}
            {!brandQuery.trim() && (
              <div className="rounded-lg border border-dashed border-border/60 bg-muted/20 p-6 text-center space-y-2">
                <Building2 className="size-8 mx-auto text-muted-foreground/50" />
                <p className="text-sm text-foreground/70">
                  输入关键词开始排查
                </p>
                <p className="text-[11px] text-muted-foreground leading-relaxed">
                  支持品牌名、类目、律所关键词搜索<br />
                  例：Dior、Barbie、(G)I-DLE、鞋类、GBC<br />
                  品牌名归一化匹配：gidle / GIDLE / GI-DLE / (G)I-DLE 均可命中
                </p>
                <p className="text-[10px] text-muted-foreground/70">
                  SellerDefense 品牌库 · 收录 {SELLER_DEFENSE_BRANDS.length} 个高频维权品牌
                </p>
              </div>
            )}

            {/* 有输入且有匹配 */}
            {brandQuery.trim() && brandResults.length > 0 && (
              <>
                {/* 计数行 */}
                <div className="flex items-center justify-between text-[11px] text-muted-foreground">
                  <span className="flex items-center gap-1.5">
                    <Building2 className="size-3.5" style={{ color: theme.primary }} />
                    匹配 <span className="font-medium text-foreground">{brandResults.length}</span> 个
                    <span className="text-muted-foreground/60">· 共 {SELLER_DEFENSE_BRANDS.length} 条</span>
                  </span>
                  {brandResults.length > 20 && (
                    <span>显示前 20 条，可滚动查看</span>
                  )}
                </div>

                {/* 品牌列表：最多显示 20 条，超出滚动 */}
                <div className="space-y-1.5 max-h-[420px] overflow-y-auto pr-1">
                  {brandResults.slice(0, 20).map((b) => (
                    <div
                      key={b.brand}
                      className="flex items-start gap-2.5 p-2.5 rounded-md border border-border/50 hover:border-border hover:bg-muted/20 transition-colors"
                    >
                      <div className="shrink-0 mt-0.5">
                        <Badge
                          variant={b.risk === 'high' ? 'destructive' : b.risk === 'medium' ? 'secondary' : 'outline'}
                          className="text-[10px] px-1.5 py-0 h-auto"
                        >
                          {b.risk === 'high' ? '高风险' : b.risk === 'medium' ? '中风险' : '低风险'}
                        </Badge>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between gap-2">
                          <span className="text-sm font-semibold text-foreground truncate">{b.brand}</span>
                          {b.troCases > 0 && (
                            <span className="text-[10px] text-muted-foreground shrink-0">
                              TRO {b.troCases} 案
                            </span>
                          )}
                        </div>
                        <div className="text-[11px] text-muted-foreground mt-0.5">
                          {b.owner} · {b.category}
                        </div>
                        <div className="flex items-center gap-2 mt-1 flex-wrap">
                          <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted/50 text-muted-foreground">
                            🏛️ {b.lawFirm}
                          </span>
                          {b.types.map((t, i) => (
                            <span key={i} className="text-[10px] px-1.5 py-0.5 rounded bg-muted/50 text-muted-foreground">
                              {t === 'trademark' ? '商标' : t === 'copyright' ? '版权' : t === 'patent' ? '专利' : 'TRO'}
                            </span>
                          ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                {brandResults.length > 20 && (
                  <p className="text-[10px] text-muted-foreground text-center">
                    还有 {brandResults.length - 20} 条结果，建议缩小关键词精确排查
                  </p>
                )}
              </>
            )}

            {/* 有输入但无匹配 */}
            {brandQuery.trim() && brandResults.length === 0 && (
              <div className="rounded-lg border border-dashed border-border/60 bg-muted/20 p-6 text-center space-y-2">
                <ShieldAlert className="size-8 mx-auto text-muted-foreground/50" />
                <p className="text-sm text-foreground/70 font-medium">
                  未收录
                </p>
                <p className="text-[11px] text-muted-foreground leading-relaxed">
                  品牌库暂未收录「{brandQuery.trim()}」<br />
                  建议自行网络搜索或运营表排查
                </p>
                <button
                  onClick={() => setBrandQuery('')}
                  className="text-[11px] text-primary hover:underline"
                >
                  重新搜索
                </button>
              </div>
            )}

            <p className="text-[10px] text-muted-foreground/70 text-center pt-1">
              数据来源：SellerDefense 公开收录 · 仅供参考，以官方公告为准
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}
