export interface IInfringementKeyword {
  id: string;
  /** 词条（品牌名 / 关键词 / 图案描述） */
  keyword: string;
  /** 风险类型：trademark（商标）/ copyright（版权）/ patent（专利）/ tro（TRO律所）/ image（图案侵权） */
  type: 'trademark' | 'copyright' | 'patent' | 'tro' | 'image';
  /** 风险等级 */
  risk: 'high' | 'medium' | 'low';
  /** 来源 sheet */
  sheet: '封店中奖词库' | '封店中奖图库' | '侵权图库壹' | '侵权图库贰';
  /** 品牌/权利方 */
  brand?: string;
  /** 说明 */
  description?: string;
  /** 相关律所（TRO 用） */
  lawFirm?: string;
}

