// ============================================================
// 本地词库搜索
// 输入关键词字符串，返回匹配结果（按风险等级排序）
// ============================================================
export function searchInLocalLibrary(query: string): {
  hits: IInfringementKeyword[];
  highestRisk: 'high' | 'medium' | 'low';
  riskLabel: string;
  riskReason: string;
  suggestion?: string;
} {
  const trimmed = query.trim().toLowerCase();
  if (!trimmed) {
    return { hits: [], highestRisk: 'low', riskLabel: '未输入', riskReason: '请输入关键词后再检测' };
  }

  const hits: IInfringementKeyword[] = [];
  const tokens = trimmed.split(/\s+/).filter(Boolean);

  // 全字段匹配（关键词 / 品牌 / 描述）
  for (const item of INFRINGEMENT_KEYWORDS) {
    const kwLower = item.keyword.toLowerCase();
    const brandLower = (item.brand || '').toLowerCase();
    const descLower = (item.description || '').toLowerCase();

    // 整词匹配优先
    if (trimmed.includes(kwLower) || kwLower.includes(trimmed)) {
      hits.push(item);
      continue;
    }
    // 品牌名匹配
    if (brandLower && trimmed.includes(brandLower)) {
      hits.push(item);
      continue;
    }
    // 多 token 部分匹配（至少 2 个 token 同时命中）
    if (tokens.length >= 2) {
      const matchCount = tokens.filter(t =>
        kwLower.includes(t) || brandLower.includes(t) || descLower.includes(t)
      ).length;
      if (matchCount >= Math.min(2, tokens.length)) {
        hits.push(item);
      }
    }
  }

  // 去重（按 id）
  const uniqueHits = Array.from(new Map(hits.map(h => [h.id, h])).values());

  // 按风险等级排序：high → medium → low
  const riskOrder: Record<string, number> = { high: 0, medium: 1, low: 2 };
  uniqueHits.sort((a, b) => riskOrder[a.risk] - riskOrder[b.risk]);

  const hasHigh = uniqueHits.some(h => h.risk === 'high');
  const hasMedium = uniqueHits.some(h => h.risk === 'medium');
  const hasLow = uniqueHits.some(h => h.risk === 'low');

  let highestRisk: 'high' | 'medium' | 'low' = 'low';
  let riskLabel = '';
  let riskReason = '';
  let suggestion = '';

  if (hasHigh) {
    highestRisk = 'high';
    riskLabel = '高风险';
    riskReason = `本地词库命中 ${uniqueHits.filter(h => h.risk === 'high').length} 条高风险词条（${uniqueHits.filter(h => h.risk === 'high').slice(0, 3).map(h => h.keyword).join('、')}${uniqueHits.filter(h => h.risk === 'high').length > 3 ? '...' : ''}），建议立即下架或更换。`;
    suggestion = '建议：① 立即下架相关 listing；② 更换为原创设计/通用名；③ 必要时咨询知识产权律师。';
  } else if (hasMedium) {
    highestRisk = 'medium';
    riskLabel = '中风险';
    riskReason = `本地词库命中 ${uniqueHits.filter(h => h.risk === 'medium').length} 条中风险词条，需进一步核实。`;
    suggestion = '建议：① 检查产品图是否使用了原创图案；② 核对关键词是否为品牌商标；③ 不确定时走搜索引擎交叉验证。';
  } else if (hasLow) {
    highestRisk = 'low';
    riskLabel = '低风险';
    riskReason = `本地词库命中 ${uniqueHits.filter(h => h.risk === 'low').length} 条低风险词条（多为通用商标名），通常不直接封店。`;
    suggestion = '建议：使用通用描述替代品牌名，避免直接使用注册商标作为关键词。';
  } else {
    highestRisk = 'low';
    riskLabel = '未命中';
    riskReason = '本地 1531 条词库中未直接命中该关键词。';
    suggestion = '⚠️ 未命中不代表零风险。建议：① 使用下方搜索引擎链接进一步核实；② 上传产品图做视觉比对；③ 不确定时咨询专业知识产权顾问。';
  }

  return { hits: uniqueHits, highestRisk, riskLabel, riskReason, suggestion };
}

