// ============================================================
// 品牌库（从 INFRINGEMENT_KEYWORDS + SELLER_DEFENSE 合并去重）
// 供品牌检索、类目浏览使用
// ============================================================
export const BRAND_LIBRARY = SELLER_DEFENSE_BRANDS.map(b => ({
  brand: b.brand,
  owner: b.owner,
  category: b.category,
  lawFirm: b.lawFirm,
  risk: b.risk,
  troCases: b.troCases ?? 0,
  types: b.enforcementTypes,
}));

// 归一化：去掉括号、横线、空格、全转小写，用于宽松匹配
// 例如 "(G)I-DLE" → "gidle"，"GI-DLE" → "gidle"
function normalizeBrandText(s: string): string {
  return s
    .toLowerCase()
    .replace(/[()\[\]{}【】（）]/g, '')  // 各类括号
    .replace(/[\-_—–·.・\s]/g, '')    // 横线、点、空格
    .trim();
}

// 在品牌库中搜索（品牌名 / 类目 / 律所模糊匹配）
// 品牌名支持归一化匹配：忽略大小写、括号、横线、空格
export function searchBrandLibrary(query: string): typeof BRAND_LIBRARY {
  const rawQ = query.trim();
  const q = rawQ.toLowerCase();
  if (!q) return BRAND_LIBRARY;
  const qNorm = normalizeBrandText(rawQ);
  return BRAND_LIBRARY.filter(b => {
    // 品牌名：精确包含 + 归一化包含双保险
    const brandLower = b.brand.toLowerCase();
    const brandNorm = normalizeBrandText(b.brand);
    if (brandLower.includes(q) || brandNorm.includes(qNorm)) return true;
    // 所属方
    if (b.owner.toLowerCase().includes(q)) return true;
    // 类目
    if (b.category.toLowerCase().includes(q)) return true;
    // 律所
    if (b.lawFirm.toLowerCase().includes(q)) return true;
    return false;
  }).sort((a, b) => {
    // 高风险排前面
    const rank: Record<string, number> = { high: 3, medium: 2, low: 1 };
    return rank[b.risk] - rank[a.risk];
  });
}

