// A+ 产品描述富文本渲染：简易安全解析器，只支持 h2/h3/p/ul/li/b/strong/br
// 有 HTML 标签 → 解析为排版后的 React 元素；无标签 → 纯文本分段；异常降级为纯文本
function APlusDescription({ html }: { html: string }) {
  if (!html || typeof html !== 'string') {
    return <p className="text-sm text-muted-foreground">暂无描述</p>;
  }
  const hasHtml = /<\/?[a-z][\s\S]*>/i.test(html);
  if (!hasHtml) {
    return <p className="text-sm text-foreground/80 leading-relaxed whitespace-pre-line">{html}</p>;
  }

  try {
    const nodes = parseSimpleHtml(html);
    return <div className="space-y-2 text-sm text-foreground/85 leading-relaxed">{nodes}</div>;
  } catch {
    // 解析失败降级：剥离所有标签，纯文本分段显示
    const plain = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    return <p className="text-sm text-foreground/80 leading-relaxed whitespace-pre-line">{plain}</p>;
  }
}

// 简易 HTML 解析器：只处理 h2/h3/p/ul/li/b/strong/br，嵌套最多一层（ul>li>b）
function parseSimpleHtml(html: string): React.ReactNode[] {
  const result: React.ReactNode[] = [];
  // 先按块级标签分段
  let remaining = html;
  let keyCounter = 0;

  const blockRegex = /<(h2|h3|p|ul)>([\s\S]*?)<\/\1>/gi;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  // 收集所有块匹配
  const blocks: { tag: string; content: string; start: number; end: number }[] = [];
  while ((match = blockRegex.exec(html)) !== null) {
    blocks.push({ tag: match[1].toLowerCase(), content: match[2], start: match.index, end: match.index + match[0].length });
  }

  for (let i = 0; i < blocks.length; i++) {
    const b = blocks[i];
    // 块之间的纯文本也展示（防止遗漏）
    if (b.start > lastIndex) {
      const stray = html.slice(lastIndex, b.start).replace(/^[\s\n\r]+|[\s\n\r]+$/g, '');
      if (stray.length > 0 && /\S/.test(stray)) {
        result.push(<p key={`stray-${keyCounter++}`} className="text-sm">{renderInline(stray, () => `stray-${keyCounter++}`)}</p>);
      }
    }
    lastIndex = b.end;

    if (b.tag === 'ul') {
      // 解析 li 子项
      const liItems: React.ReactNode[] = [];
      const liRegex = /<li>([\s\S]*?)<\/li>/gi;
      let liMatch: RegExpExecArray | null;
      let liIdx = 0;
      while ((liMatch = liRegex.exec(b.content)) !== null) {
        liItems.push(
          <li key={`li-${liIdx++}`} className="flex gap-2">
            <span className="text-primary shrink-0 mt-0.5">•</span>
            <span className="flex-1">{renderInline(liMatch[1], () => `li-in-${liIdx}`)}</span>
          </li>
        );
      }
      // 没解析到 li 就直接显示文本
      if (liItems.length === 0) {
        result.push(<p key={`ul-${keyCounter++}`}>{renderInline(b.content, () => `ul-${keyCounter++}`)}</p>);
      } else {
        result.push(<ul key={`ul-${keyCounter++}`} className="list-none space-y-1 pl-1">{liItems}</ul>);
      }
    } else if (b.tag === 'h2') {
      result.push(
        <h2 key={`h2-${keyCounter++}`} className="text-base font-bold text-foreground pt-1">
          {renderInline(b.content, () => `h2-${keyCounter++}`)}
        </h2>
      );
    } else if (b.tag === 'h3') {
      result.push(
        <h3 key={`h3-${keyCounter++}`} className="text-sm font-semibold text-foreground mt-2">
          {renderInline(b.content, () => `h3-${keyCounter++}`)}
        </h3>
      );
    } else {
      // p 或其他，渲染为段落
      result.push(
        <p key={`p-${keyCounter++}`} className="text-sm">
          {renderInline(b.content, () => `p-${keyCounter++}`)}
        </p>
      );
    }
  }

  // 末尾残留文本
  if (lastIndex < html.length) {
    const tail = html.slice(lastIndex).replace(/^[\s\n\r]+|[\s\n\r]+$/g, '');
    if (tail.length > 0 && /\S/.test(tail)) {
      result.push(<p key={`tail-${keyCounter++}`} className="text-sm">{renderInline(tail, () => `tail-${keyCounter++}`)}</p>);
    }
  }

  // 一个块都没解析出来 → 直接纯文本分段
  if (result.length === 0) {
    const plain = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    result.push(<p key="plain-0">{plain}</p>);
  }

  return result;
}

// 渲染行内标签：<b> / <strong> / <br> / <br/>
function renderInline(text: string, nextKey: () => string): React.ReactNode[] {
  const nodes: React.ReactNode[] = [];
  let idx = 0;
  const len = text.length;

  while (idx < len) {
    // 找下一个 < 开头的标签
    const ltIdx = text.indexOf('<', idx);
    if (ltIdx === -1) {
      nodes.push(text.slice(idx));
      break;
    }
    // 标签前的纯文本
    if (ltIdx > idx) {
      nodes.push(text.slice(idx, ltIdx));
    }
    // 找标签结束 >
    const gtIdx = text.indexOf('>', ltIdx);
    if (gtIdx === -1) {
      // 没有闭合 >，把剩余当纯文本
      nodes.push(text.slice(ltIdx));
      break;
    }
    const tagFull = text.slice(ltIdx, gtIdx + 1); // 例如 <b> 或 </b> 或 <br/>
    const tagInner = tagFull.slice(1, -1).trim().toLowerCase(); // 如 b, /b, br/

    if (tagInner.startsWith('/')) {
      // 结束标签（单独遇到的结束标签，直接跳过当纯文本不渲染）
      idx = gtIdx + 1;
      continue;
    }

    // 自闭合 <br> / <br/>
    if (tagInner === 'br' || tagInner === 'br/' || tagInner === 'br /') {
      nodes.push(<br key={nextKey()} />);
      idx = gtIdx + 1;
      continue;
    }

    // <b> 或 <strong> 开始标签
    if (tagInner === 'b' || tagInner === 'strong') {
      const tagName = tagInner;
      const closeTag = `</${tagName}>`;
      const closeIdx = text.toLowerCase().indexOf(closeTag, gtIdx + 1);
      if (closeIdx === -1) {
        // 没有闭合，跳过标签本身，后面内容继续按纯文本
        idx = gtIdx + 1;
      } else {
        const innerText = text.slice(gtIdx + 1, closeIdx);
        nodes.push(
          <strong key={nextKey()} className="font-semibold text-foreground">
            {renderInline(innerText, nextKey)}
          </strong>
        );
        idx = closeIdx + closeTag.length;
      }
      continue;
    }

    // 其他不认识的标签：跳过标签本身，内容当纯文本继续
    idx = gtIdx + 1;
  }

  return nodes.length > 0 ? nodes : [''];
}

function getHeatFromTitle(title: string): number {
  let hash = 0;
  for (let i = 0; i < title.length; i++) {
    hash = (hash * 31 + title.charCodeAt(i)) >>> 0;
  }
  return 50 + (hash % 50);
}

