function pickKeywords(count: number, seed: number): string[] {
  const result: string[] = [];
  const pool = [...KEYWORD_POOL];
  for (let i = 0; i < count && pool.length > 0; i++) {
    const idx = (seed + i * 7) % pool.length;
    result.push(pool.splice(idx, 1)[0]);
  }
  return result;
}

