function pickFrom<T>(arr: T[], count: number, seed: number): T[] {
  const result: T[] = [];
  const pool = [...arr];
  for (let i = 0; i < count && pool.length > 0; i++) {
    const idx = (seed + i * 7 + 3) % pool.length;
    result.push(pool.splice(idx, 1)[0]);
  }
  return result;
}

