// 亚马逊类目名翻译：命中则返回「英文（中文）」，未命中返回原文
function tr(name: string): string {
  const zh = AMAZON_ZH_MAP[name.trim()];
  return zh ? `${name}（${zh}）` : name;
}

export default function CategoryExplorer({ theme }: CategoryExplorerProps) {
  // 数据状态
  const [amazonData, setAmazonData] = useState<AmazonData | null>(null);
  const [tkData, setTkData] = useState<TkData | null>(null);
  const [amazonLoading, setAmazonLoading] = useState(false);
  const [tkLoading, setTkLoading] = useState(false);
  const [amazonError, setAmazonError] = useState<string | null>(null);
  const [tkError, setTkError] = useState<string | null>(null);

  // 识别输入
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<{
    amazon: { id: string; path: string; node: AmazonNode; score: number }[];
    tk: { id: string; name: string; nameZh: string; path: string; site: string[]; score: number; isLeaf: boolean }[];
  } | null>(null);
  const [searching, setSearching] = useState(false);

  // 浏览状态
  const [activePlatform, setActivePlatform] = useState<'amazon' | 'tk'>('amazon');
  const [tkSite, setTkSite] = useState('us');
  // 亚马逊展开的节点 id 集合（树形展开模式）
  const [amazonExpanded, setAmazonExpanded] = useState<Set<string>>(new Set());
  // TK 展开的节点 id 集合
  const [tkExpanded, setTkExpanded] = useState<Set<string>>(new Set());

  // 选中的节点详情
  const [selectedNode, setSelectedNode] = useState<{
    platform: 'amazon' | 'tk';
    id: string;
    name: string;
    nameZh?: string;
    fullPath: string;
    isLeaf: boolean;
    childrenCount: number;
    siblingCount: number;
    site?: string[];
    department?: string;
  } | null>(null);

  const detailRef = useRef<HTMLDivElement>(null);

  // 站点中文名
  const SITE_NAMES: Record<string, string> = {
    us: '美区', th: '泰国', my: '马来', id: '印尼', ph: '菲律宾', vn: '越南', sg: '新加坡',
    jp: '日本', mx: '墨西哥',
  };

  // ==================== 加载数据（超时 + 3次重试 + 24h 缓存 + 相对路径） ====================
  const CACHE_TTL = 24 * 60 * 60 * 1000; // 24小时
  const MAX_RETRIES = 3;
  const FETCH_TIMEOUT = 30000; // 30秒

  async function fetchWithRetry(url: string): Promise<Response> {
    let lastErr: unknown = null;
    for (let i = 0; i < MAX_RETRIES; i++) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT);
      try {
        const res = await fetch(url, { signal: controller.signal });
        clearTimeout(timer);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res;
      } catch (e) {
        clearTimeout(timer);
        lastErr = e;
        if (i < MAX_RETRIES - 1) {
          // 指数退避：1s, 2s, 4s
          const delay = Math.pow(2, i) * 1000;
          logger.warn(`[cat-explorer] 第${i + 1}次加载失败，${delay / 1000}s后重试`, String(e));
          await new Promise(r => setTimeout(r, delay));
        }
      }
    }
    throw lastErr;
  }

  function getCache<T>(key: string): T | null {
    try {
      const raw = scopedStorage.getItem(key);
      if (!raw) return null;
      const cached = JSON.parse(raw) as { t: number; d: T };
      if (Date.now() - cached.t > CACHE_TTL) return null;
      return cached.d;
    } catch {
      return null;
    }
  }

  function setCache(key: string, data: unknown) {
    try {
      scopedStorage.setItem(key, JSON.stringify({ t: Date.now(), d: data }));
    } catch (e) {
      // 存储可能已满（2.5MB JSON 超 quota），静默忽略
      logger.warn('[cat-explorer] 缓存写入失败', String(e));
    }
  }

  const loadAmazon = useCallback(async () => {
    if (amazonData) return;
    // 先读缓存
    const cached = getCache<AmazonData>('cat_amazon_v1');
    if (cached) {
      setAmazonData(cached);
      logger.info('[cat-explorer] 亚马逊类目命中缓存', `${cached.total}节点`);
      return;
    }
    setAmazonLoading(true);
    setAmazonError(null);
    try {
      const res = await fetchWithRetry('./assets/amazon_categories.json');
      const data = await res.json() as AmazonData;
      setAmazonData(data);
      setCache('cat_amazon_v1', data);
      logger.info('[cat-explorer] 亚马逊类目加载完成', `${data.total}节点/${data.departments.length}部门`);
    } catch (e) {
      logger.error('[cat-explorer] 亚马逊类目加载失败', String(e));
      setAmazonError(String(e));
    } finally {
      setAmazonLoading(false);
    }
  }, [amazonData]);

  const loadTk = useCallback(async () => {
    if (tkData) return;
    // 先读缓存
    const cached = getCache<TkData>('cat_tk_v1');
    if (cached) {
      setTkData(cached);
      logger.info('[cat-explorer] TK类目命中缓存', `${cached.tree.length}个一级类目`);
      return;
    }
    setTkLoading(true);
    setTkError(null);
    try {
      const res = await fetchWithRetry('./assets/tk_categories.json');
      const data = await res.json() as TkData;
      setTkData(data);
      setCache('cat_tk_v1', data);
      logger.info('[cat-explorer] TK类目加载完成', `${data.tree.length}个一级类目, ${data.sites.length}站点`);
    } catch (e) {
      logger.error('[cat-explorer] TK类目加载失败', String(e));
      setTkError(String(e));
    } finally {
      setTkLoading(false);
    }
  }, [tkData]);

  // 切tab时加载对应数据
  useEffect(() => {
    if (activePlatform === 'amazon') loadAmazon();
    else loadTk();
  }, [activePlatform, loadAmazon, loadTk]);

  // ==================== 工具函数 ====================

  // 中文→英文映射
  function normalizeQuery(q: string): string {
    let normalized = q.trim().toLowerCase();
    // 逐字替换中文词
    for (const [zh, en] of Object.entries(ZH_EN_MAP)) {
      if (normalized.includes(zh.toLowerCase())) {
        normalized = normalized.replaceAll(zh.toLowerCase(), en);
      }
    }
    return normalized;
  }

  // 亚马逊：递归查找节点路径（嵌套树结构）
  function findAmazonNodePath(
    tree: AmazonNode[],
    nodeId: string,
    pathArr: AmazonNode[] = [],
  ): AmazonNode[] | null {
    for (const node of tree) {
      if (node.id === nodeId) return [...pathArr, node];
      if (node.children && node.children.length > 0) {
        const result = findAmazonNodePath(node.children, nodeId, [...pathArr, node]);
        if (result) return result;
      }
    }
    return null;
  }

  function findAmazonNodeById(tree: AmazonNode[], id: string): AmazonNode | null {
    for (const n of tree) {
      if (n.id === id) return n;
      if (n.children) {
        const r = findAmazonNodeById(n.children, id);
        if (r) return r;
      }
    }
    return null;
  }

  // TK：递归找节点并拼路径
  function findTkNodePath(
    tree: TkNode[],
    nodeId: string,
    pathArr: { id: string; name: string; nameZh: string }[] = [],
  ): { id: string; name: string; nameZh: string }[] | null {
    for (const node of tree) {
      if (node.id === nodeId) {
        return [...pathArr, { id: node.id, name: node.name, nameZh: node.nameZh || '' }];
      }
      if (node.children) {
        const result = findTkNodePath(node.children, nodeId, [
          ...pathArr,
          { id: node.id, name: node.name, nameZh: node.nameZh || '' },
        ]);
        if (result) return result;
      }
    }
    return null;
  }

  // 过滤某站点的 TK 一级类目
  function getTkLevel1BySite(tree: TkNode[], site: string): TkNode[] {
    return tree.filter((n) => n.site.includes(site));
  }

  // 过滤某站点的 TK 子类目
  function getTkChildrenBySite(node: TkNode, site: string): TkNode[] {
    return (node.children || []).filter((n) => n.site.includes(site));
  }

  // ==================== 识别搜索 ====================
  const handleSearch = useCallback(() => {
    if (!searchQuery.trim() || !amazonData && !tkData) return;
    setSearching(true);

    const normalized = normalizeQuery(searchQuery);
    const terms = normalized.split(/\s+/).filter(Boolean);
    if (terms.length === 0) { setSearching(false); return; }

    // 亚马逊匹配（嵌套树递归）
    const amazonResults: { id: string; path: string; node: AmazonNode; score: number }[] = [];
    if (amazonData) {
      function walkAmazon(nodes: AmazonNode[], pathArr: string[]) {
        for (const node of nodes) {
          const nameLower = node.name.toLowerCase();
          const zhLower = (node.nameZh || '').toLowerCase();
          let score = 0;
          for (const term of terms) {
            if (nameLower.includes(term)) score += 2;
            if (zhLower && zhLower.includes(term)) score += 2;
          }
          if (score > 0) {
            // 路径匹配加分
            for (const p of pathArr) {
              for (const term of terms) {
                if (p.toLowerCase().includes(term)) score += 0.5;
              }
            }
            // 末级节点（无children）加权
            const isLeaf = !node.children || node.children.length === 0;
            if (isLeaf) score += 1;
            if (score >= 2) {
              const fullPath = [...pathArr, node.nameZh ? `${node.name}（${node.nameZh}）` : node.name].join(' > ');
              amazonResults.push({
                id: node.id,
                path: fullPath,
                node,
                score,
              });
            }
          }
          if (node.children && node.children.length > 0) {
            walkAmazon(node.children, [...pathArr, node.name]);
          }
        }
      }
      walkAmazon(amazonData.departments, []);
      amazonResults.sort((a, b) => b.score - a.score);
    }

    // TK匹配
    const tkResults: { id: string; name: string; nameZh: string; path: string; site: string[]; score: number; isLeaf: boolean }[] = [];
    if (tkData) {
      function walkTk(nodes: TkNode[], pathArr: string[]) {
        for (const node of nodes) {
          const nameLower = node.name.toLowerCase();
          const zhLower = (node.nameZh || '').toLowerCase();
          let score = 0;
          for (const term of terms) {
            if (nameLower.includes(term)) score += 2;
            if (zhLower && zhLower.includes(term)) score += 2;
          }
          if (score > 0) {
            // 路径匹配加分
            for (const p of pathArr) {
              for (const term of terms) {
                if (p.toLowerCase().includes(term)) score += 0.5;
              }
            }
            // 末级（无children）加权
            if (!node.children || node.children.length === 0) score += 1;
            if (score >= 2) {
              const fullPath = [...pathArr, node.nameZh ? `${node.name} (${node.nameZh})` : node.name].join(' > ');
              tkResults.push({
                id: node.id,
                name: node.name,
                nameZh: node.nameZh || '',
                path: fullPath,
                site: node.site || [],
                score,
                isLeaf: !node.children || node.children.length === 0,
              });
            }
          }
          if (node.children) walkTk(node.children, [...pathArr, node.name]);
        }
      }
      walkTk(tkData.tree, []);
      tkResults.sort((a, b) => b.score - a.score);
    }

    setSearchResults({
      amazon: amazonResults.slice(0, 8),
      tk: tkResults.slice(0, 5),
    });
    setSearching(false);
  }, [searchQuery, amazonData, tkData]);

  // ==================== 浏览交互（树形展开） ====================

  // 亚马逊：切换节点展开/收起
  const toggleAmazonNode = useCallback((nodeId: string) => {
    setAmazonExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(nodeId)) {
        next.delete(nodeId);
      } else {
        next.add(nodeId);
      }
      return next;
    });
  }, []);

  // 亚马逊：选中节点显示详情
  const selectAmazonNode = useCallback((nodeId: string) => {
    if (!amazonData) return;
    const pathNodes = findAmazonNodePath(amazonData.departments, nodeId) || [];
    const node = pathNodes[pathNodes.length - 1];
    if (!node) return;
    const isLeaf = !node.children || node.children.length === 0;
    // 算兄弟数
    let siblingCount = 0;
    if (pathNodes.length <= 1) {
      siblingCount = amazonData.departments.length;
    } else {
      const parentNode = pathNodes[pathNodes.length - 2];
      siblingCount = parentNode.children?.length || 0;
    }
    const fullPath = pathNodes.map((p) => p.nameZh ? `${p.name}（${p.nameZh}）` : p.name).join(' > ');
    setSelectedNode({
      platform: 'amazon',
      id: nodeId,
      name: node.nameZh ? `${node.name}（${node.nameZh}）` : node.name,
      nameZh: node.nameZh,
      fullPath,
      isLeaf,
      childrenCount: node.children?.length || 0,
      siblingCount,
      department: pathNodes[0]?.nameZh ? `${pathNodes[0].name}（${pathNodes[0].nameZh}）` : pathNodes[0]?.name || '',
    });
    detailRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, [amazonData]);

  // TK：切换节点展开/收起
  const toggleTkNode = useCallback((nodeId: string) => {
    setTkExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(nodeId)) {
        next.delete(nodeId);
      } else {
        next.add(nodeId);
      }
      return next;
    });
  }, []);

  // TK：选中节点显示详情
  const selectTkNode = useCallback((node: TkNode) => {
    if (!tkData) return;
    const pathNodes = findTkNodePath(tkData.tree, node.id) || [];
    const fullPath = pathNodes.map((p) => p.nameZh ? `${p.name} (${p.nameZh})` : p.name).join(' > ');
    // 找父节点算兄弟数
    let siblingCount = 0;
    if (pathNodes.length <= 1) {
      siblingCount = getTkLevel1BySite(tkData.tree, tkSite).length;
    } else {
      const parentId = pathNodes[pathNodes.length - 2]?.id;
      const parentNode = findTkNodeById(tkData.tree, parentId);
      if (parentNode) {
        siblingCount = getTkChildrenBySite(parentNode, tkSite).length;
      }
    }
    setSelectedNode({
      platform: 'tk',
      id: node.id,
      name: node.name,
      nameZh: node.nameZh || '',
      fullPath,
      isLeaf: !node.children || node.children.length === 0,
      childrenCount: node.children?.length || 0,
      siblingCount,
      site: node.site,
    });
    detailRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, [tkData, tkSite]);

  function findTkNodeById(tree: TkNode[], id: string): TkNode | null {
    for (const n of tree) {
      if (n.id === id) return n;
      if (n.children) {
        const r = findTkNodeById(n.children, id);
        if (r) return r;
      }
    }
    return null;
  }

  // 从识别结果点击，跳转到浏览位置并展开路径、选中节点
  const goToAmazonResult = useCallback((nodeId: string) => {
    if (!amazonData) return;
    const pathNodes = findAmazonNodePath(amazonData.departments, nodeId) || [];
    setActivePlatform('amazon');
    // 展开路径上所有父节点（不含目标节点本身，因为叶子不需要展开）
    const parentIds = pathNodes.slice(0, -1).map((n) => n.id);
    setAmazonExpanded((prev) => {
      const next = new Set(prev);
      parentIds.forEach((id) => next.add(id));
      return next;
    });
    setTimeout(() => {
      selectAmazonNode(nodeId);
    }, 50);
  }, [amazonData, selectAmazonNode]);

  const goToTkResult = useCallback((nodeId: string) => {
    if (!tkData) return;
    const pathNodes = findTkNodePath(tkData.tree, nodeId) || [];
    setActivePlatform('tk');
    const parentIds = pathNodes.slice(0, -1).map((n) => n.id);
    setTkExpanded((prev) => {
      const next = new Set(prev);
      parentIds.forEach((id) => next.add(id));
      return next;
    });
    setTimeout(() => {
      const node = findTkNodeById(tkData.tree, nodeId);
      if (node) selectTkNode(node);
    }, 50);
  }, [tkData, selectTkNode]);

  // ==================== 渲染：识别结果 ====================
  const renderSearchResults = () => {
    if (!searchResults) return null;
    const hasResults = searchResults.amazon.length > 0 || searchResults.tk.length > 0;

    if (!hasResults) {
      return (
        <div className="p-4 text-center text-xs text-muted-foreground rounded-lg bg-muted/30">
          未匹配到明确类目，可换更具体的关键词，或用手动浏览
        </div>
      );
    }

    return (
      <div className="space-y-4">
        {/* 亚马逊结果 */}
        {searchResults.amazon.length > 0 && (
          <div>
            <div className="text-xs font-medium text-foreground mb-2 flex items-center gap-1">
              <span className="text-[11px] px-1.5 py-0.5 rounded bg-primary/10 text-primary font-medium">亚马逊</span>
              匹配 {searchResults.amazon.length} 个类目
            </div>
            <div className="space-y-1.5">
              {searchResults.amazon.map((r) => (
                <button
                  key={r.id}
                  onClick={() => goToAmazonResult(r.id)}
                  className="w-full text-left p-2.5 rounded-lg hover:bg-muted/50 transition-colors border border-transparent hover:border-border/50"
                >
                  <div className="text-xs font-medium text-foreground flex items-center gap-1.5">
                    {(!r.node.children || r.node.children.length === 0) && <Badge variant="outline" className="text-[10px] h-4 px-1">末级</Badge>}
                    <span className="truncate">{r.node.nameZh ? `${r.node.name}（${r.node.nameZh}）` : r.node.name}</span>
                  </div>
                  <div className="text-[10px] text-muted-foreground mt-0.5 truncate">
                    {r.path}
                  </div>
                  <div className="text-[10px] text-muted-foreground/70 mt-0.5">
                    得分: {r.score.toFixed(1)} · 子节点: {r.node.children?.length || 0}
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* TK结果 */}
        {searchResults.tk.length > 0 && (
          <div>
            <div className="text-xs font-medium text-foreground mb-2 flex items-center gap-1">
              <span className="text-[11px] px-1.5 py-0.5 rounded" style={{ backgroundColor: theme.primaryLight + '40', color: theme.primary }}>TikTok</span>
              匹配 {searchResults.tk.length} 个类目
            </div>
            <div className="space-y-1.5">
              {searchResults.tk.map((r) => (
                <button
                  key={r.id}
                  onClick={() => goToTkResult(r.id)}
                  className="w-full text-left p-2.5 rounded-lg hover:bg-muted/50 transition-colors border border-transparent hover:border-border/50"
                >
                  <div className="text-xs font-medium text-foreground flex items-center gap-1.5">
                    {r.isLeaf && <Badge variant="outline" className="text-[10px] h-4 px-1">末级</Badge>}
                    <span className="truncate">{r.name}</span>
                    {r.nameZh && <span className="text-muted-foreground font-normal">（{r.nameZh}）</span>}
                  </div>
                  <div className="text-[10px] text-muted-foreground mt-0.5 truncate">
                    {r.path}
                  </div>
                  <div className="text-[10px] mt-0.5 flex flex-wrap gap-1">
                    {r.site.slice(0, 5).map((s) => (
                      <span key={s} className="px-1 py-0.5 rounded bg-muted text-muted-foreground">
                        {SITE_NAMES[s] || s}
                      </span>
                    ))}
                    {r.site.length > 5 && (
                      <span className="px-1 py-0.5 rounded bg-muted text-muted-foreground">+{r.site.length - 5}</span>
                    )}
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  // ==================== 渲染：亚马逊浏览（树形展开） ====================
  const renderAmazonBrowser = () => {
    if (!amazonData) return null;

    const sortedDepts = [...amazonData.departments].sort(
      (a, b) => (b.count || 0) - (a.count || 0),
    );

    // 递归渲染树节点
    function renderNode(node: AmazonNode, level: number): JSX.Element {
      const hasChildren = node.children && node.children.length > 0;
      const isExpanded = amazonExpanded.has(node.id);
      const isSelected = selectedNode?.platform === 'amazon' && selectedNode.id === node.id;

      return (
        <div key={node.id}>
          <div
            className={cn(
              'w-full px-2 py-1.5 rounded-md flex items-center justify-between gap-2 transition-colors group',
              isSelected
                ? 'bg-primary/10 text-primary'
                : 'hover:bg-muted/60',
            )}
            style={{ paddingLeft: `${level * 14 + 8}px` }}
          >
            <div className="flex items-center gap-1.5 min-w-0 flex-1">
              {hasChildren ? (
                <button
                  onClick={() => toggleAmazonNode(node.id)}
                  className="shrink-0 size-4 flex items-center justify-center rounded hover:bg-muted text-muted-foreground"
                  aria-label={isExpanded ? '收起' : '展开'}
                  type="button"
                >
                  <ChevronRight
                    className={cn(
                      'size-3 transition-transform duration-200',
                      isExpanded && 'rotate-90',
                    )}
                  />
                </button>
              ) : (
                <span className="shrink-0 size-4" />
              )}
              <button
                onClick={() => selectAmazonNode(node.id)}
                className="min-w-0 flex-1 text-left" 
                type="button"
              >
                <div className={cn(
                  'text-xs truncate',
                  isSelected ? 'text-primary font-medium' : 'text-foreground',
                )}>
                  {node.name}
                </div>
                {node.nameZh && (
                  <div className="text-[10px] text-muted-foreground truncate">
                    {node.nameZh}
                  </div>
                )}
              </button>
              {!hasChildren && (
                <Badge variant="outline" className="shrink-0 text-[10px] h-4 px-1">末级</Badge>
              )}
            </div>
            {hasChildren && (
              <span className="text-[10px] text-muted-foreground shrink-0 tabular-nums">
                {node.children!.length}
              </span>
            )}
          </div>
          {hasChildren && isExpanded && (
            <div className="overflow-hidden">
              {node.children!.map((child) => renderNode(child, level + 1))}
            </div>
          )}
        </div>
      );
    }

    return (
      <div className="space-y-2">
        <div className="flex items-center justify-between text-[11px] text-muted-foreground px-1">
          <span>共 {sortedDepts.length} 个一级部门 · 总计 {amazonData.total} 节点</span>
          <button
            onClick={() => {
              setAmazonExpanded(new Set());
              setSelectedNode(null);
            }}
            className="hover:text-foreground transition-colors"
          >
            全部收起
          </button>
        </div>
        <div className="max-h-[420px] overflow-y-auto -mx-1 px-1 space-y-0.5">
          {sortedDepts.map((node) => renderNode(node, 0))}
        </div>
      </div>
    );
  };

  // ==================== 渲染：TK浏览（树形展开） ====================
  const renderTkBrowser = () => {
    if (!tkData) return null;

    const level1Nodes = getTkLevel1BySite(tkData.tree, tkSite);

    // 递归渲染树节点（按当前站点过滤）
    function renderNode(node: TkNode, level: number): JSX.Element {
      const children = getTkChildrenBySite(node, tkSite);
      const hasChildren = children.length > 0;
      const isExpanded = tkExpanded.has(node.id);
      const isSelected = selectedNode?.platform === 'tk' && selectedNode.id === node.id;

      return (
        <div key={node.id}>
          <div
            className={cn(
              'w-full px-2 py-1.5 rounded-md flex items-center justify-between gap-2 transition-colors group',
              isSelected
                ? 'bg-primary/10 text-primary'
                : 'hover:bg-muted/60',
            )}
            style={{ paddingLeft: `${level * 14 + 8}px` }}
          >
            <div className="flex items-center gap-1.5 min-w-0 flex-1">
              {hasChildren ? (
                <button
                  onClick={() => toggleTkNode(node.id)}
                  className="shrink-0 size-4 flex items-center justify-center rounded hover:bg-muted text-muted-foreground"
                  aria-label={isExpanded ? '收起' : '展开'}
                  type="button"
                >
                  <ChevronRight
                    className={cn(
                      'size-3 transition-transform duration-200',
                      isExpanded && 'rotate-90',
                    )}
                  />
                </button>
              ) : (
                <span className="shrink-0 size-4" />
              )}
              <button
                onClick={() => selectTkNode(node)}
                className="min-w-0 flex-1 text-left"
                type="button"
              >
                <div className={cn(
                  'text-xs truncate',
                  isSelected ? 'text-primary font-medium' : 'text-foreground',
                )}>
                  {node.name}
                </div>
                {node.nameZh && (
                  <div className="text-[10px] text-muted-foreground truncate">
                    {node.nameZh}
                  </div>
                )}
              </button>
              {!hasChildren && (
                <Badge variant="outline" className="shrink-0 text-[10px] h-4 px-1">末级</Badge>
              )}
            </div>
            {hasChildren && (
              <span className="text-[10px] text-muted-foreground shrink-0 tabular-nums">
                {children.length}
              </span>
            )}
          </div>
          {hasChildren && isExpanded && (
            <div className="overflow-hidden">
              {children.map((child) => renderNode(child, level + 1))}
            </div>
          )}
        </div>
      );
    }

    return (
      <div className="space-y-2">
        {/* 站点选择 */}
        <div className="flex flex-wrap gap-1.5">
          {tkData.sites.map((site) => (
            <button
              key={site}
              onClick={() => {
                setTkSite(site);
                setTkExpanded(new Set());
                setSelectedNode(null);
              }}
              className={cn(
                'text-[11px] px-2 py-1 rounded-full transition-colors',
                tkSite === site
                  ? 'text-white'
                  : 'bg-muted text-muted-foreground hover:text-foreground',
              )}
              style={tkSite === site ? { backgroundColor: theme.primary } : undefined}
            >
              {SITE_NAMES[site] || site}
            </button>
          ))}
        </div>

        <div className="flex items-center justify-between text-[11px] text-muted-foreground px-1">
          <span>{SITE_NAMES[tkSite] || tkSite} · {level1Nodes.length} 个一级类目</span>
          <button
            onClick={() => {
              setTkExpanded(new Set());
              setSelectedNode(null);
            }}
            className="hover:text-foreground transition-colors"
          >
            全部收起
          </button>
        </div>

        <div className="max-h-[420px] overflow-y-auto -mx-1 px-1 space-y-0.5">
          {level1Nodes.length === 0 ? (
            <div className="text-center text-xs text-muted-foreground py-8">
              该站点下没有类目数据
            </div>
          ) : (
            level1Nodes.map((node) => renderNode(node, 0))
          )}
        </div>
      </div>
    );
  };

  // ==================== 渲染：详情 ====================
  const renderDetail = () => {
    if (!selectedNode) {
      return (
        <div className="text-center text-xs text-muted-foreground py-6">
          <Eye className="size-8 mx-auto mb-2 opacity-30" />
          点击识别结果或浏览列表中的类目，查看类目透视详情
        </div>
      );
    }

    return (
      <Card className="border-0 bg-muted/20">
        <CardContent className="p-3 space-y-2">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0 flex-1">
              <div className="text-sm font-semibold text-foreground flex items-center gap-1.5">
                {selectedNode.isLeaf && <Badge variant="outline" className="text-[10px] h-5 px-1.5">末级类目</Badge>}
                <span className="truncate">{selectedNode.name}</span>
                {selectedNode.nameZh && (
                  <span className="text-muted-foreground font-normal text-xs">（{selectedNode.nameZh}）</span>
                )}
              </div>
              <div className="text-[11px] text-muted-foreground mt-0.5 leading-relaxed">
                {selectedNode.fullPath}
              </div>
            </div>
            <Badge
              variant="outline"
              className="shrink-0 text-[10px] h-5 px-1.5"
              style={{
                color: selectedNode.platform === 'amazon' ? theme.primary : theme.primaryLight ? theme.primary : undefined,
                borderColor: theme.primary + '30',
              }}
            >
              {selectedNode.platform === 'amazon' ? '亚马逊' : 'TikTok Shop'}
            </Badge>
          </div>

          <div className="grid grid-cols-3 gap-2 text-[11px]">
            <div className="p-2 rounded-md bg-background/80">
              <div className="text-muted-foreground text-[10px] mb-0.5">直接子节点</div>
              <div className="font-semibold tabular-nums text-foreground">{selectedNode.childrenCount}</div>
            </div>
            <div className="p-2 rounded-md bg-background/80">
              <div className="text-muted-foreground text-[10px] mb-0.5">同层兄弟</div>
              <div className="font-semibold tabular-nums text-foreground">{selectedNode.siblingCount}</div>
            </div>
            <div className="p-2 rounded-md bg-background/80">
              <div className="text-muted-foreground text-[10px] mb-0.5">层级深度</div>
              <div className="font-semibold tabular-nums text-foreground">
                {selectedNode.fullPath.split(' > ').length}
              </div>
            </div>
          </div>

          {selectedNode.platform === 'amazon' && selectedNode.department && (
            <div className="text-[11px]">
              <span className="text-muted-foreground">所属顶层部门：</span>
              <span className="text-foreground">{selectedNode.department}</span>
            </div>
          )}

          {selectedNode.platform === 'tk' && selectedNode.site && (
            <div className="text-[11px]">
              <span className="text-muted-foreground">适用站点：</span>
              <span className="text-foreground">
                {selectedNode.site.map((s) => SITE_NAMES[s] || s).join(' / ')}
              </span>
            </div>
          )}

          {selectedNode.platform === 'amazon' && (
            <div className="text-[11px]">
              <span className="text-muted-foreground">节点ID：</span>
              <span className="text-foreground font-mono text-[10px]">{selectedNode.id}</span>
            </div>
          )}

          <div className="text-[10px] text-muted-foreground/70 pt-1 border-t border-border/30">
            数据来源：
            {selectedNode.platform === 'amazon'
              ? `Amazon 类目树快照 · ${amazonData?.captured || '未知时间'}`
              : `TikTok Shop 官方类目 · ${tkData?.version || '2026-10'}`}
          </div>
        </CardContent>
      </Card>
    );
  };

  // ==================== 加载态 ====================
  const renderLoading = (platform: string) => (
    <div className="py-12 text-center">
      <Loader2 className="size-6 mx-auto animate-spin text-muted-foreground mb-2" />
      <p className="text-xs text-muted-foreground">类目数据加载中…</p>
      <p className="text-[10px] text-muted-foreground/70 mt-1">全量数据约 2.5MB，请稍候</p>
    </div>
  );

  const renderError = (platform: string, error: string, retry: () => void) => (
    <div className="py-10 text-center space-y-3">
      <div className="text-xs text-destructive">加载失败：{error}</div>
      <Button size="sm" variant="outline" onClick={retry} className="gap-1.5">
        <RefreshCw className="size-3.5" />
        重试
      </Button>
    </div>
  );

  // ==================== 主渲染 ====================
  return (
    <div className="space-y-3">
      {/* 功能一：类目识别 */}
      <div className="space-y-2">
        <div className="text-xs font-medium text-foreground flex items-center gap-1.5">
          <Search className="size-3.5" style={{ color: theme.primary }} />
          产品类目识别
        </div>
        <div className="flex gap-2">
          <div className="relative flex-1">
            <Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
              placeholder="输入产品名，中英文均可"
              className="pl-8 text-xs h-9"
            />
          </div>
          <Button
            size="sm"
            onClick={handleSearch}
            disabled={searching || !searchQuery.trim()}
            className="h-9"
            style={{ backgroundColor: theme.primary }}
          >
            {searching ? <Loader2 className="size-3.5 animate-spin" /> : <Search className="size-3.5" />}
            <span className="ml-1">识别</span>
          </Button>
        </div>
        <div className="text-[10px] text-muted-foreground">
          提示：支持中英文，常见品类词已内置映射（如「手机壳→phone case」「露营→camping」「毛绒玩具→plush」）
        </div>

        {searchResults && renderSearchResults()}
      </div>

      {/* 分割线 */}
      <div className="border-t border-border/40" />

      {/* 功能二+三：浏览 + 透视 */}
      <div className="space-y-2">
        <div className="text-xs font-medium text-foreground flex items-center gap-1.5">
          <Layers className="size-3.5" style={{ color: theme.primary }} />
          类目树浏览
        </div>

        <Tabs value={activePlatform} onValueChange={(v) => setActivePlatform(v as 'amazon' | 'tk')}>
          <TabsList className="w-full h-7 bg-muted/50">
            <TabsTrigger value="amazon" className="text-xs py-0.5 data-[state=active]:shadow-none">
              亚马逊
            </TabsTrigger>
            <TabsTrigger value="tk" className="text-xs py-0.5 data-[state=active]:shadow-none">
              TikTok Shop
            </TabsTrigger>
          </TabsList>

          <TabsContent value="amazon" className="mt-2 space-y-3">
            {amazonLoading && renderLoading('amazon')}
            {amazonError && renderError('amazon', amazonError, () => { setAmazonData(null); loadAmazon(); })}
            {!amazonLoading && !amazonError && amazonData && renderAmazonBrowser()}
          </TabsContent>

          <TabsContent value="tk" className="mt-2 space-y-3">
            {tkLoading && renderLoading('tk')}
            {tkError && renderError('tk', tkError, () => { setTkData(null); loadTk(); })}
            {!tkLoading && !tkError && tkData && renderTkBrowser()}
          </TabsContent>
        </Tabs>
      </div>

      {/* 功能三：类目透视详情 */}
      <div ref={detailRef} className="space-y-2">
        <div className="text-xs font-medium text-foreground flex items-center gap-1.5">
          <Eye className="size-3.5" style={{ color: theme.primary }} />
          类目透视
        </div>
        {renderDetail()}
      </div>
    </div>
  );
}
